#pragma once
/* Served only on the temporary password-protected AP. No external assets. */
#define CAST_PORTAL_BEGIN "<!doctype html><html lang=zh-CN><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><title>AI Passport 配网</title><style>body{background:#202122;color:#eef0f3;font:16px system-ui;max-width:440px;margin:36px auto;padding:20px}input,button{box-sizing:border-box;width:100%;padding:12px;margin:8px 0 20px;border-radius:8px;border:1px solid #606670;font:inherit}button{background:#397ffc;color:white}p{line-height:1.6}#result{white-space:pre-wrap}</style><h1>AI Passport 配网</h1><p>连接 2.4 GHz Wi-Fi。保存前会测试连接；失败时保留原配置。</p><form id=f><label>Wi-Fi 名称<input name=ssid required maxlength=32 autocomplete=off></label><label>Wi-Fi 密码（开放网络留空）<input name=password type=password maxlength=63 autocomplete=new-password></label><label>更新服务地址<input name=origin type=url required placeholder='https://你的域名' maxlength=160></label><p>本机联调可用 http://192.168.x.x:8766 等局域网地址。此处填写服务根地址，不带末尾斜杠或 /api 路径。</p><button id=save>测试连接并保存</button></form><p id=result></p><script>const token='"
#define CAST_PORTAL_END "';const form=document.getElementById('f'),result=document.getElementById('result'),button=document.getElementById('save');let pending=false;form.onsubmit=async e=>{e.preventDefault();button.disabled=true;try{const r=await fetch('/configure',{method:'POST',headers:{'Content-Type':'application/json','X-Setup-Token':token},body:JSON.stringify(Object.fromEntries(new FormData(form)))});const d=await r.json();if(!r.ok)throw Error(d.error||'提交失败');pending=true;form.password.value='';result.textContent='正在连接，请等待约 30 秒。'}catch(e){result.textContent=e.message;button.disabled=false}};setInterval(async()=>{if(!pending)return;try{const r=await fetch('/status'),s=await r.json();if(s.state===5){pending=false;result.textContent='Wi-Fi 配置已保存。热点即将关闭，请回到设备手动检查更新。';}else if(s.state===4||s.state===6){pending=false;button.disabled=false;result.textContent=s.state===6?'存储失败，原配置已保留。':'连接失败，请检查名称、密码及 2.4 GHz 网络。原配置已保留。';}}catch(e){result.textContent='热点连接已中断，请查看设备状态；不能据此确认保存成功。'}},1500);</script></html>"
